<script setup lang="ts">
import { computed, onMounted, ref, shallowRef, watch } from 'vue'
import { collapsedMemberIds } from '../utils/localGraph'
import CharacterRelationCanvas from './CharacterRelationCanvas.vue'
import CharacterPortrait from './CharacterPortrait.vue'
import PortraitPreview from './PortraitPreview.vue'
import EntityNames from './EntityNames.vue'
import { matchesEntityName } from '../utils/entityNames'
import CharacterNetworkInsights from './CharacterNetworkInsights.vue'
import type { CharacterPath } from '../utils/characterAnalysis'
import type { CharacterGraph, RelationType } from '../types/characterGraph'
import { characterTypeLabel, filterCharacterGraph, relatedCharacters, relationDefinitions, relationStyles, relationTypes, relationshipText } from '../utils/characterGraph'

const detailPanel = ref<HTMLElement>()
function showDetails() { detailPanel.value?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth', block: 'start' }) }
const props = defineProps<{ graph: CharacterGraph; initialSelectedId?: string | null }>()
const emit=defineEmits<{nodeSelected:[id:string|null];edgeSelected:[id:string|null]}>()
const sourceFilter=shallowRef('ALL'), collapsed=shallowRef(new Set<string>()), focusDepth=shallowRef(1)
const hiddenMembers=computed(()=>collapsedMemberIds(props.graph,collapsed.value))
function toggleOrganization(id:string){const next=new Set(collapsed.value);next.has(id)?next.delete(id):next.add(id);collapsed.value=next}
const graph = computed(() => props.graph)
const search = ref('')
const selectedId = ref<string | null>(null), selectedEdgeId = ref<string | null>(null)
const showPortraits = shallowRef(true), highlightedPath = shallowRef<CharacterPath | null>(null)
function highlightPath(path: CharacterPath | null) { highlightedPath.value = path; if (path) clearSelection() }
const activeTypes = ref<RelationType[]>([...relationTypes]), focusOnly = ref(false), showSpoilers = ref(false), showEnded = ref(true), showUnlinked = ref(true), showEdgeLabels = ref(true)
const nodeLimit = ref(24)
watch(()=>props.graph,()=>{if(selectedId.value&&!props.graph.nodes.some(node=>node.id===selectedId.value))clearSelection();if(selectedEdgeId.value&&!props.graph.edges.some(edge=>edge.id===selectedEdgeId.value))clearSelection()})
onMounted(() => { if (window.matchMedia('(max-width: 600px)').matches) nodeLimit.value = 8 })
const roleFilter = ref(''), entityFilter = ref(0), layout = ref<'network' | 'circular' | 'roster'>('network'), resetKey = ref(0)
const eligibleEdges = computed(() => (graph.value?.edges || []).filter(e => (sourceFilter.value==='ALL'||(sourceFilter.value==='LOCAL'?e.dataSource==='LOCAL':e.dataSource!=='LOCAL')) && !collapsed.value.has(e.target) && (showSpoilers.value || !e.spoiler) && (showEnded.value || !e.ended)))
const visible = computed(() => {
  const eligibleNodes = (graph.value?.nodes || []).filter(n => (!hiddenMembers.value.has(n.id)||n.id===selectedId.value) && (!roleFilter.value || n.role === roleFilter.value) && (!entityFilter.value || (n.characterType || 1) === entityFilter.value))
  const result = filterCharacterGraph(eligibleNodes, eligibleEdges.value, activeTypes.value, null)
  if(focusOnly.value && selectedId.value) {
    const included=new Set([selectedId.value]);for(let hop=0;hop<focusDepth.value;hop++){const frontier=new Set(included);for(const edge of result.edges)if(frontier.has(edge.source)||frontier.has(edge.target)){included.add(edge.source);included.add(edge.target)}}
    result.nodes=result.nodes.filter(node=>included.has(node.id));result.edges=result.edges.filter(edge=>included.has(edge.source)&&included.has(edge.target))
  }
  const connected = new Set(result.edges.flatMap(e => [e.source, e.target]))
  const pool = showUnlinked.value || !eligibleEdges.value.length || focusOnly.value ? result.nodes : result.nodes.filter(n => connected.has(n.id))
  const degree = new Map(pool.map(n => [n.id, result.edges.filter(e => e.source === n.id || e.target === n.id).length]))
  const preferred = new Set<string>(selectedId.value ? [selectedId.value] : [])
  for (const edge of result.edges) if (edge.source === selectedId.value || edge.target === selectedId.value || edge.id === selectedEdgeId.value) { preferred.add(edge.source); preferred.add(edge.target) }
  const nodes = [...pool].sort((a,b) => Number(b.id === selectedId.value) - Number(a.id === selectedId.value) || Number(preferred.has(b.id)) - Number(preferred.has(a.id)) || (degree.get(b.id) || 0) - (degree.get(a.id) || 0) || a.label.localeCompare(b.label,'zh-CN')).slice(0,nodeLimit.value)
  const ids = new Set(nodes.map(n => n.id))
  const scoped = result.edges.filter(e => ids.has(e.source) && ids.has(e.target))
  return { nodes, edges: scoped.slice(0,400), edgeTotal: scoped.length }
})
const organizationMembers = computed(() => graph.value.edges.filter(edge => edge.dataSource==='LOCAL' && edge.relationType==='MEMBER' && edge.target===selectedId.value && (showSpoilers.value||!edge.spoiler)))
const selectedNode = computed(() => graph.value?.nodes.find(n => n.id === selectedId.value))
const selectedEdge = computed(() => visible.value.edges.find(e => e.id === selectedEdgeId.value))
const related = computed(() => selectedId.value ? relatedCharacters(graph.value?.nodes || [], visible.value.edges, selectedId.value) : [])
const characters = computed(() => (graph.value?.nodes || []).filter(n => matchesEntityName(n, search.value, [n.role, n.group])))
const typeCount = (type: RelationType) => eligibleEdges.value.filter(e => e.relationType === type).length
const groups = computed(() => [...new Set(relationDefinitions.filter(d => !d.legacy || graph.value?.edges.some(e => e.relationType === d.code)).map(d => d.group))].map(group => ({ code: group, name: relationDefinitions.find(d => d.group === group)!.groupLabel, types: relationDefinitions.filter(d => d.group === group && (!d.legacy || graph.value?.edges.some(e => e.relationType === d.code))) })))
const usedTypes = computed(() => relationDefinitions.filter(d => typeCount(d.code) > 0))
const activeOfficialCount = computed(() => activeTypes.value.filter(t => !relationStyles[t].legacy).length)
const hiddenSpoilers = computed(() => (graph.value?.edges || []).filter(e => e.spoiler).length)
const connectedCount = computed(() => new Set(visible.value.edges.flatMap(e => [e.source, e.target])).size)
const nameOf = (id: string) => graph.value?.nodes.find(n => n.id === id)?.label || id
const safeLink = (url?: string | null) => url && /^https?:\/\//i.test(url) ? url : undefined

function selectNode(id: string) { emit('nodeSelected',id);selectedId.value = id; selectedEdgeId.value = null; if (!visible.value.nodes.some(n => n.id === id)) { showUnlinked.value = true; roleFilter.value = ''; entityFilter.value = 0 } }
function selectEdge(id: string) { emit('edgeSelected',id);selectedEdgeId.value = id; selectedId.value = null; focusOnly.value = false }
function clearSelection() { emit('nodeSelected',null);emit('edgeSelected',null);selectedId.value = null; selectedEdgeId.value = null; focusOnly.value = false }
function reset() { sourceFilter.value='ALL';collapsed.value=new Set();focusDepth.value=1;nodeLimit.value = window.matchMedia('(max-width: 600px)').matches ? 8 : 24; clearSelection(); highlightedPath.value = null; showPortraits.value = true; activeTypes.value = [...relationTypes]; roleFilter.value = ''; entityFilter.value = 0; showUnlinked.value = true; showSpoilers.value = false; showEnded.value = true; showEdgeLabels.value = true; layout.value = 'network'; search.value = ''; resetKey.value++ }
watch(()=>props.initialSelectedId,id=>{if(id)selectNode(id)},{immediate:true})
</script>
<template><div class="character-graph-workspace">
      <p v-if="graph.meta.truncated" class="notice">当前为部分来源结果；尚未加载的官方资料可稍后补充，本地扩展独立保留。</p>
      <p v-if="!graph.edges.length" class="notice">当前关系资料可能不完整，以下显示名册；可在上方添加有依据的本地关系。没有连线不表示角色之间没有关系。</p>
      <div class="graph-counts"><span><strong>{{ graph.nodes.length }}</strong>已加载角色</span><span><strong>{{ visible.edges.length }}</strong>可见关系</span><span><strong>{{ connectedCount }}</strong>关联角色</span></div>
      <CharacterNetworkInsights :key="graph.work.uid + ':' + resetKey" :nodes="visible.nodes" :edges="visible.edges" :selected-id="selectedId" :truncated="graph.meta.truncated" @select-node="selectNode" @select-edge="selectEdge" @path-change="highlightPath" />
      <div class="graph-workspace">
        <section class="graph-main-panel" aria-label="角色网络">
          <header class="graph-panel-heading"><div><small>角色与组织 · 空间关系视图</small><h2>{{ graph.work.title }}</h2></div><div class="segmented" aria-label="图谱布局"><button v-for="(label, code) in { network: '疏朗网络', circular: '环形总览', roster: '角色名册' }" :key="code" :class="{ active: layout === code }" :aria-pressed="layout === code" @click="layout = code">{{ label }}</button></div></header>
          <div class="graph-filter-bar"><label>关系来源<select v-model="sourceFilter"><option value="ALL">全部关系</option><option value="BANGUMI">仅 Bangumi 关系</option><option value="LOCAL">仅本地关系</option></select></label><label>画布规模<select v-model.number="nodeLimit"><option :value="8">8 个节点</option><option :value="24">24 个节点</option><option :value="48">48 个节点</option><option :value="1000">全部已加载节点</option></select></label><label>出场定位<select v-model="roleFilter"><option value="">全部定位</option><option>主角</option><option>配角</option><option>闲角</option><option>客串</option></select></label><label>实体种类<select v-model.number="entityFilter"><option :value="0">全部种类</option><option :value="1">角色</option><option :value="2">机体</option><option :value="3">舰船</option><option :value="4">组织</option></select></label><details class="taxonomy"><summary>关系分类 <span>{{ activeOfficialCount }}/28</span></summary><div class="taxonomy-popover"><div class="taxonomy-heading"><strong>按 Bangumi 类别筛选</strong><button @click="activeTypes = [...relationTypes]">全选</button><button @click="activeTypes = []">清空</button></div><fieldset v-for="group in groups" :key="group.code"><legend>{{ group.name }}</legend><label v-for="type in group.types" :key="type.code"><input v-model="activeTypes" type="checkbox" :value="type.code"><i :style="{ background: type.color }"></i>{{ type.label }}<small>{{ typeCount(type.code) }}</small></label></fieldset></div></details><button class="reset-button" @click="reset">↺ 重置</button></div>
          <div v-if="usedTypes.length" class="relation-legend"><label v-for="type in usedTypes" :key="type.code"><input v-model="activeTypes" type="checkbox" :value="type.code"><i :style="{ background: type.color }"></i>{{ type.label }} <small>{{ typeCount(type.code) }}</small></label></div>
          <div class="visibility-controls"><label><input v-model="showPortraits" type="checkbox">显示角色头像</label><label><input v-model="showSpoilers" type="checkbox">显示剧透关系<span v-if="hiddenSpoilers">（{{ hiddenSpoilers }}）</span></label><label><input v-model="showEnded" type="checkbox">包含已结束</label><label><input v-model="showUnlinked" type="checkbox">显示暂无连线角色</label><label><input v-model="showEdgeLabels" type="checkbox">显示全部关系文字</label><label><input v-model="focusOnly" type="checkbox" :disabled="!selectedId">仅看选中角色</label></div>
          <div v-if="selectedNode || selectedEdge" class="selection-bar"><button v-if="selectedNode?.dataSource==='LOCAL' && selectedNode.characterType===4" @click="toggleOrganization(selectedNode.id)">{{ collapsed.has(selectedNode.id)?'展开组织成员':'折叠组织成员' }}</button><label v-if="focusOnly">邻域<select v-model.number="focusDepth"><option :value="1">直接关系</option><option :value="2">包含二级关系</option></select></label><span>{{ selectedNode ? `正在查看：${selectedNode.label}` : '已选中一条关系' }}</span><button v-if="selectedNode" @click="focusOnly = !focusOnly">{{ focusOnly ? '返回完整网络' : '只看直接关系' }}</button><button @click="showDetails">查看详情</button><button @click="clearSelection">取消选择</button></div>
          <p v-if="visible.edgeTotal > 400" class="notice">当前范围有 {{ visible.edgeTotal }} 条关系，画布最多绘制400条；可缩小角色范围后查看。</p><CharacterRelationCanvas :focus-on-selection="true" v-if="visible.nodes.length" :nodes="visible.nodes" :edges="visible.edges" :selected-id="selectedId" :selected-edge-id="selectedEdgeId" :layout="layout" :reset-key="resetKey" :show-edge-labels="showEdgeLabels" :show-portraits="showPortraits" :path="highlightedPath" @clear-selection="clearSelection" @select-node="selectNode" @select-edge="selectEdge" />
          <div v-else class="graph-state"><h3>当前筛选下暂无角色</h3><button @click="reset">恢复默认筛选</button></div>
          <footer class="graph-panel-footer"><span>显示 {{ visible.nodes.length }} / {{ graph.nodes.length }} 角色 · {{ visible.edges.length }} 条关系</span><span>箭头：起点相对终点的身份 · 虚线：本地添加 · 点线：官方已结束</span></footer>
        </section>
        <aside class="graph-side-panel" aria-label="角色与关系详情">
          <section class="character-list-section"><div class="section-label"><h2>角色索引</h2><span>{{ graph.nodes.length }}</span></div><label class="character-search"><span class="visually-hidden">搜索中文名或原名</span><input v-model="search" type="search" placeholder="搜索中文名 / 原名"></label><div class="character-index"><button v-for="node in characters" :key="node.id" :aria-label="`选择角色 ${node.label}`" :aria-pressed="selectedId === node.id" :class="{ selected: selectedId === node.id }" @click="selectNode(node.id)"><CharacterPortrait :node="node"/><span class="index-copy"><strong>{{ node.label }}</strong><small>{{ node.role }} · {{ characterTypeLabel(node.characterType) }}</small></span><span class="index-arrow">↗</span></button><p v-if="!characters.length" class="muted">没有匹配角色。</p></div></section>
          <section ref="detailPanel" class="character-detail-section" aria-live="polite">
            <template v-if="selectedEdge"><p class="detail-eyebrow">RELATIONSHIP / 关系详情</p><span class="relationship-badge" :style="{ color: relationStyles[selectedEdge.relationType].color, background: relationStyles[selectedEdge.relationType].tint }">{{ selectedEdge.label }}</span><span v-if="selectedEdge.ended" class="status-badge">已结束</span><span v-if="selectedEdge.spoiler" class="status-badge">剧透</span><h3>{{ nameOf(selectedEdge.source) }} {{ selectedEdge.directed ? '→' : '—' }} {{ nameOf(selectedEdge.target) }}</h3><p v-if="selectedEdge.directed" class="direction-note">{{ nameOf(selectedEdge.source) }} 是 {{ nameOf(selectedEdge.target) }} 的{{ selectedEdge.label }}</p><p class="detail-description">{{ selectedEdge.description }}</p><dl><dt>关系出处</dt><dd>{{ selectedEdge.evidence }}</dd><dt>数据来源</dt><dd>{{ selectedEdge.dataSource==='LOCAL'?'本地添加':selectedEdge.sourceName }}</dd><template v-if="selectedEdge.notes"><dt>本地备注</dt><dd>{{ selectedEdge.notes }}</dd></template><template v-if="selectedEdge.sourceRelationId"><dt>原始关系类型</dt><dd>{{ selectedEdge.sourceRelationId }}</dd></template><template v-if="selectedEdge.archiveRevision"><dt>归档版本（SHA256）</dt><dd>{{ selectedEdge.archiveRevision }}</dd></template></dl><a v-if="safeLink(selectedEdge.sourceUrl)" :href="safeLink(selectedEdge.sourceUrl)" target="_blank" rel="noopener noreferrer" class="source-link">查看来源 ↗</a></template>
            <template v-else-if="selectedNode"><p class="detail-eyebrow">CHARACTER / 角色档案</p><div class="selected-character-title"><CharacterPortrait :node="selectedNode" large/><div><h3>{{ selectedNode.label }}</h3><p v-if="selectedNode.originalName && selectedNode.originalName !== selectedNode.label">{{ selectedNode.originalName }}</p><small>{{ selectedNode.role }} · {{ characterTypeLabel(selectedNode.characterType) }}</small></div></div><a v-if="safeLink(selectedNode.nameCnSource)" :href="safeLink(selectedNode.nameCnSource)" target="_blank" rel="noopener noreferrer" class="source-link">中文名来源 ↗</a><p class="source-badge">{{ selectedNode.dataSource==='LOCAL'?'本地添加':'Bangumi 官方资料' }}</p><p v-if="selectedNode.gender">性别：{{ selectedNode.gender }}</p><p v-if="selectedNode.organizationType">组织类型：{{ selectedNode.organizationType }}</p><EntityNames :node="selectedNode"/><PortraitPreview :node="selectedNode"/><p class="detail-description">{{ selectedNode.description }}</p><a v-if="/^character:bangumi:[1-9]\d*$/.test(selectedNode.id)" class="source-link" :href="`https://bgm.tv/character/${selectedNode.id.split(':').at(-1)}`" target="_blank" rel="noopener noreferrer">查看角色完整资料 ↗</a><RouterLink v-else-if="selectedNode.dataSource!=='LOCAL'" class="source-link" :to="`/characters/${encodeURIComponent(selectedNode.id)}`">打开完整档案 ↗</RouterLink><p v-if="selectedNode.notes">备注：{{ selectedNode.notes }}</p><button v-if="selectedNode.dataSource==='LOCAL' && selectedNode.characterType===4" @click="toggleOrganization(selectedNode.id)">{{ collapsed.has(selectedNode.id)?'展开组织成员':'折叠组织成员' }}</button><div v-if="selectedNode.characterType===4"><h4>组织成员（{{ organizationMembers.length }}）</h4><button v-for="member in organizationMembers" :key="member.id" @click="selectNode(member.source)">{{ nameOf(member.source) }} · {{ member.label }}</button><p v-if="!organizationMembers.length" class="muted">暂无成员，可在“人物关系 / 成员”中添加。</p></div><h4>关联人物 / 组织 <small>{{ related.length }} 条</small></h4><div class="character-relations"><button v-for="item in related" :key="item.edge.id" @click="selectEdge(item.edge.id)"><i :style="{ background: relationStyles[item.edge.relationType].color }"></i><strong>{{ item.character.label }}</strong><small>{{ relationshipText(item.edge, item.outgoing) }}</small><span>›</span></button><p v-if="!related.length" class="muted">当前筛选下暂无已收录关系。</p></div></template>
            <div v-else class="selection-hint"><span>◎</span><h3>从一个角色开始</h3><p>点击节点或索引查看档案，<br>点击连线核对关系与出处。</p><small>颜色区分出场定位，节点大小体现直接关联人数；选中后仅突出相关连线。</small></div>
          </section>
        </aside>
      </div>
      <p class="graph-source-footnote">{{ graph.meta.notice }} 角色中文名优先采用来源明确标注的简体中文名，保留原名；暂无来源时不强行翻译。</p>
</div></template>
<style scoped>
.graph-counts{margin:0 0 16px!important;padding:10px 20px;justify-content:flex-start}.graph-counts strong{font-size:20px!important}
.cross-work-actions{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.cross-work-actions a{font-size:12px;color:#668670;border-bottom:1px solid #c8d8c2;padding:7px 2px}
.selection-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:10px 18px;background:#edf4e9;border-bottom:1px solid #dce7d4;color:#5b7950;font-size:11px}.selection-bar span{margin-right:auto;overflow-wrap:anywhere}.selection-bar button{font-size:10px;padding:7px 10px;min-height:34px}.graph-main-panel{scroll-margin-top:18px}
